#!/usr/bin/env bash
# Generate the browser script for the linear-solve submodule (src/vendor/linear-solve).
#
# Upstream gauss-jordan.js is a CommonJS module: it attaches to an ambient `exports`
# (never declared locally) and ends with `module.exports = linear`. Loaded as a bare
# browser <script> that throws (`exports`/`module` undeclared). We wrap the upstream
# file *verbatim* in an IIFE that supplies a LOCAL `module`/`exports` and returns it,
# assigned to the global `linear`. The module/exports stay local — leaking a global
# `module` would flip later UMD libs (uzip, paper, sha1) into CommonJS mode and stop
# them defining their browser globals.
#
# Output (committed, so a plain clone needs no rebuild): linear-solve.js
# (LICENSE is authored once — upstream ships no LICENSE file, only "license": "MIT".)
#
# Re-run after `git submodule update`:
#   ./build.sh
set -euo pipefail
cd "$(dirname "$0")"
SUB="../../linear-solve"

{
  echo "// Generated by build.sh from the linear-solve submodule — do not edit by hand."
  echo "// Upstream: https://github.com/lovasoa/linear-solve (MIT). Exposes global \`linear\`."
  echo "var linear = (function () {"
  echo "  var module = { exports: {} };"
  echo "  var exports = module.exports;"
  cat "$SUB/gauss-jordan.js"
  echo "  return module.exports;"
  echo "})();"
} > ./linear-solve.js

# Sanity: load it with no ambient module/exports (browser-like) and exercise the API.
node -e '
  const fs = require("fs");
  const src = fs.readFileSync("./linear-solve.js","utf8");
  const linear = new Function(src + "\nreturn linear;")();
  const inv = JSON.stringify(linear.invert([[2,0],[0,2]]));
  const sol = JSON.stringify(linear.solve([[1,2],[3,4]],[5,11]));
  if (inv !== "[[0.5,0],[0,0.5]]" || sol !== "[1,2]") {
    console.error("ERROR: self-test failed — invert="+inv+" solve="+sol); process.exit(1);
  }
  if (typeof module !== "undefined") { /* ours is local; global stays clean */ }
' || { echo "ERROR: linear-solve.js self-test failed — upstream gauss-jordan.js changed; update build.sh" >&2; exit 1; }

echo "built linear-solve.js (browser global 'linear'; self-test passed)"
